// Keep the real user gesture in one place. Backend scenario assertions do not
// encode a second, page-specific confirmation grammar.
static bool import_wav_loop(Performance& u){u.set_shift(false);for(unsigned n=0;n<5 && u.sampler_page()!=3;++n)if(!u.encoder_direction(u.sampler_page()<3?0x08:0x20))return false;u.set_shift(true);return !std::strcmp(u.soft_label(7),"FILE LOOP") && u.soft_key(7) && u.soft_key(0);}
static bool begin_import(Performance& ui,SessionFiles& files){
 bool ok=ui.soft_key(3) && ui.modal_active() && files.service();
 if(!ok)std::fprintf(stderr,"MIDI import begin: mode=%u label=%s modal=%u status=%s\n",unsigned(ui.mode()),ui.soft_label(3),ui.modal_active(),ui.browser().status);
 return ok;
}
static bool confirm_import(Performance& ui,SessionFiles& files){
 bool ok=ui.encoder_push() && files.service();
 if(!ok)std::fprintf(stderr,"MIDI import confirm: modal=%u status=%s\n",ui.modal_active(),ui.browser().status);
 return ok;
}
